/**
 * 前端类型生成器
 * IR → TypeScript 类型（按域拆文件）
 *
 * 规则：
 *   - 实体：不生成（前端不需要）
 *   - 枚举：生成在它所在域的文件里（global 枚举 → global.ts）
 *   - 视图：生成在它所在域的文件里
 *   - 引用枚举/视图：直接用名字；跨文件则 import（只一层：域 → global）
 *   - 引用实体：退化为 unknown（实体不生成）
 *   - 必填：view 看 required；实体字段看 nullable（nullable 才可选）
 *   - writeOnly 字段：只有 form 生成
 */
import { writeFileSync, mkdirSync, existsSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义',
  '',
]

/** source → 域文件 basename */
function domainOf(source) {
  if (!source) return 'unknown'
  if (source.startsWith('global/')) return 'global'
  const m = source.match(/^domains\/(.+?)\.ya?ml$/)
  return m ? m[1] : source.replace(/\.ya?ml$/, '')
}

/** 基础类型 → TS */
const PRIM = {
  id: 'string', string: 'string', text: 'string',
  int: 'number', long: 'number', number: 'number', decimal: 'number',
  boolean: 'boolean',
  date: 'string', datetime: 'string',
  json: 'unknown', array: 'unknown[]',
}

/** 解析一个字段的 TS 类型；遇到跨文件引用时写入 imports */
function tsType(fd, ownerFile, nameToFile, imports) {
  if (fd.of) {
    // 基础类型数组
    if (PRIM[fd.of]) return PRIM[fd.of] + '[]'
    return refType(fd.of, fd.resolvedOf, ownerFile, nameToFile, imports) + '[]'
  }
  const t = fd.type
  // id 字段前端一律 string（大整数精度 + 与路由参数/localStorage 一致）
  if (t === 'id') return 'string'
  if (PRIM[t]) return PRIM[t]
  return refType(t, fd.resolved, ownerFile, nameToFile, imports)
}

function refType(name, resolved, ownerFile, nameToFile, imports) {
  // entity 不给前端 → unknown（设计映射，保留）
  if (resolved.kind === 'entity') return 'unknown'
  if (resolved.kind === 'enum' || resolved.kind === 'view') {
    const targetFile = nameToFile.get(name)
    if (targetFile && targetFile !== ownerFile) {
      if (!imports.has(targetFile)) imports.set(targetFile, new Set())
      imports.get(targetFile).add(name)
    }
    return name
  }
  throw new Error('无法映射前端字段引用类型: ' + name + '（kind=' + resolved.kind + '）')
}

function renderEnum(name, def) {
  const vals = def.values
  return 'export type ' + name + ' =\n  | ' + vals.map((v) => "'" + v + "'").join('\n  | ')
}

function renderView(name, def, ownerFile, nameToFile) {
  const imports = new Map()
  const lines = []
  const required = new Set(def.required || [])
  const isForm = def.viewKind === 'form'

  const fieldLines = []
  for (const [fn, fd] of Object.entries(def.fields)) {
    if (fd.writeOnly && !isForm) continue
    // form 看 required；非 form 默认必填，除非 nullable
    let opt = ''
    if (isForm) opt = required.has(fn) ? '' : '?'
    else opt = fd.nullable ? '?' : ''
    const note = fd.note ? '  // ' + fd.note : ''
    fieldLines.push('  ' + fn + opt + ': ' + tsType(fd, ownerFile, nameToFile, imports) + note)
  }

  if (def.description) lines.push('/** ' + def.description + ' */')
  lines.push('export interface ' + name + ' {')
  lines.push(...fieldLines)
  lines.push('}')
  return { code: lines.join('\n'), imports }
}

export function generateFrontendTypes(ir, outDir) {
  if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true })

  // ① 按域分组，建 名字→文件 映射
  const groups = new Map() // file -> { enums: [], views: [] }
  const nameToFile = new Map()
  const ensure = (f) => { if (!groups.has(f)) groups.set(f, { enums: [], views: [] }); return groups.get(f) }

  for (const [name, e] of ir.enums) {
    const f = domainOf(e.source)
    ensure(f).enums.push([name, e])
    nameToFile.set(name, f)
  }
  for (const [name, v] of ir.views) {
    const f = domainOf(v.source)
    ensure(f).views.push([name, v])
    nameToFile.set(name, f)
  }

  // ② 每域生成一个文件
  const files = []
  for (const [fileBase, parts] of groups) {
    const allImports = new Map()
    const body = []

    if (parts.enums.length > 0) {
      body.push('// ============ 枚举 ============')
      for (const [name, def] of parts.enums) { body.push(renderEnum(name, def)); body.push('') }
    }
    if (parts.views.length > 0) {
      body.push('// ============ 视图 ============')
      for (const [name, def] of parts.views) {
        const { code, imports } = renderView(name, def, fileBase, nameToFile)
        for (const [t, names] of imports) {
          if (!allImports.has(t)) allImports.set(t, new Set())
          for (const n of names) allImports.get(t).add(n)
        }
        body.push(code); body.push('')
      }
    }

    const lines = [...HEADER]
    for (const target of [...allImports.keys()].sort()) {
      const names = [...allImports.get(target)].sort()
      lines.push('import type { ' + names.join(', ') + " } from './" + target + "'")
    }
    if (allImports.size > 0) lines.push('')
    lines.push(...body)

    writeFileSync(join(outDir, fileBase + '.ts'), lines.join('\n'), 'utf-8')
    files.push(fileBase + '.ts')
  }

  // ③ index.ts re-export
  const idx = [...HEADER]
  for (const f of files.sort()) {
    idx.push("export * from './" + f.replace(/\.ts$/, '') + "'")
  }
  writeFileSync(join(outDir, 'index.ts'), idx.join('\n'), 'utf-8')
  files.push('index.ts')

  console.log('  [frontend/types] ' + files.length + ' 个文件 → ' + outDir)
  for (const f of files) console.log('    - ' + f)
}
